mapper.select:



SELECT assignment_id AS "assignmentId", user_id AS "userId", role_code AS "roleCode", assignment_type AS "assignmentType", approved_by AS "approvedBy", effective_start_date AS "effectiveStartDate", effective_end_date AS "effectiveEndDate", status, use_yn AS "useYn"
FROM user_role

  AND user_id=#{userId}
  AND role_code=#{roleCode}
  AND status=#{status}

ORDER BY assignment_id

SELECT menu_id AS "menuId", parent_menu_id AS "parentMenuId", menu_type AS "menuType", menu_name AS "menuName", screen_id AS "screenId", url, icon, business_category AS "businessCategory", description, display_order AS "displayOrder", use_yn AS "useYn" FROM menu
AND menu_id LIKE CONCAT('%', #{menuId}, '%') AND menu_name LIKE CONCAT('%', #{menuName}, '%') AND screen_id=#{screenId} AND url LIKE CONCAT('%', #{url}, '%') AND business_category=#{businessCategory}
ORDER BY COALESCE(parent_menu_id, ''), display_order



SELECT permission_id AS "permissionId", target_type AS "targetType", target_id AS "targetId", menu_id AS "menuId", decision, api_path_pattern AS "apiPathPattern", use_yn AS "useYn"
FROM menu_permission

  AND target_type=#{targetType}
  AND target_id=#{targetId}

ORDER BY target_type, target_id, menu_id

SELECT group_id AS "groupId", group_name AS "groupName", description, managing_department AS "managingDepartment", status, use_yn AS "useYn" FROM code_group
AND group_id=#{groupId} AND group_name LIKE CONCAT('%', #{groupName}, '%') AND managing_department LIKE CONCAT('%', #{managingDepartment}, '%') AND status=#{status}
ORDER BY group_id



SELECT group_id AS "groupId", code_value AS "codeValue", code_name AS "codeName", parent_code_value AS "parentCodeValue", display_order AS "displayOrder", additional_attributes AS "additionalAttributes", effective_start_date AS "effectiveStartDate", effective_end_date AS "effectiveEndDate", status, use_yn AS "useYn"
FROM detail_code

  AND group_id=#{groupId}
  AND code_value=#{codeValueFilter}
  AND status=#{statusFilter}

ORDER BY display_order
